<script setup>
import {ref,watch,useId} from 'vue'
import {workbenchRequest} from '../lib/backends'
const props=defineProps({reviewId:{type:String,required:true},settings:{type:Object,required:true},sourceText:String})
const expanded=ref(false),loading=ref(false),generating=ref(false),translation=ref(null),error=ref('')
const panelId=useId();let generation=0
const preference=()=>JSON.stringify(['echomind.review-translation',props.settings.backend,props.settings.endpoints?.[props.settings.backend],props.settings.userId,props.reviewId])
function remember(){try{localStorage.setItem(preference(),expanded.value?'open':'closed')}catch{}}
async function load(create){const token=++generation;loading.value=true;error.value='';try{const path='/feedback/'+encodeURIComponent(props.reviewId)+'/translation';let result=await workbenchRequest(props.settings,path);if(token!==generation)return;if(result.state==='missing'&&create){generating.value=true;result=await workbenchRequest(props.settings,path,'POST',{user_id:props.settings.userId})}if(token!==generation)return;if(result.state==='ready'){if(props.sourceText!==undefined&&result.original_content!==props.sourceText)throw new Error('评价原文已变化，此处消息为旧快照。请到客户反馈列表核对当前评价及译文。');translation.value=result}}catch(e){if(token===generation)error.value=e.message}finally{if(token===generation){loading.value=false;generating.value=false}}}
function toggle(){expanded.value=!expanded.value;remember();if(expanded.value&&!translation.value&&!loading.value)load(true)}
watch(()=>[props.reviewId,props.sourceText,props.settings.backend,props.settings.userId,props.settings.workspaceId],()=>{generation++;translation.value=null;error.value='';loading.value=false;generating.value=false;try{expanded.value=localStorage.getItem(preference())==='open'}catch{expanded.value=false}if(expanded.value)load(false)},{immediate:true})
</script>
<template><section class="review-translation"><button type="button" class="secondary review-translation-toggle" :aria-expanded="expanded" :aria-controls="panelId" @click="toggle">{{expanded?'收起中文译文':'查看中文译文'}}</button><div v-if="expanded" :id="panelId" class="review-translation-panel" :aria-busy="loading"><h3>客户评价 · 中文译文</h3><p v-if="loading" class="source-note" role="status">{{generating?'正在生成中文译文，首次翻译需要一些时间…':'正在读取已保存译文…'}}原文可继续阅读。</p><template v-else-if="translation"><p class="review-translated-text" lang="zh-CN">{{translation.text}}</p><small class="source-note">机器翻译 · 仅帮助理解客户原意，请对照上方葡萄牙语原文核对。译文已保存，下次可直接查看。</small></template><div v-else-if="error" role="alert"><p>{{error}}</p><button type="button" class="secondary" @click="load(true)">重试中文翻译</button></div><template v-else><p class="source-note">此评价尚无已保存译文。</p><button type="button" class="secondary" @click="load(true)">生成中文译文</button></template></div></section></template>
<style scoped>
.review-translation{margin-top:14px;min-width:0}.review-translation-toggle{min-height:40px}.review-translation-panel{margin-top:12px;padding:16px;background:#f5f7ff;border:1px solid #dce3f6;border-radius:10px;overflow-wrap:anywhere}.review-translation-panel h3{margin:0 0 10px;font-size:14px}.review-translated-text{white-space:pre-wrap;line-height:1.85;margin:0 0 12px;color:#24334e}.review-translation-panel .source-note{display:block;line-height:1.65}.review-translation-panel button{min-height:40px}@media(max-width:600px){.review-translation-panel{padding:12px}}
</style>
